<script setup>import { LoaderCircle, Inbox } from 'lucide-vue-next'; defineProps({ columns: { type: Array, required: true }, rows: { type: Array, default: () => [] }, loading: Boolean, emptyText: { type: String, default: 'Belum ada data untuk ditampilkan.' }, rowKey: { type: String, default: 'id' } });</script>
<template><div class="overflow-x-auto"><table class="w-full min-w-[640px] border-collapse text-[13px]"><thead class="bg-[#F9FAFB]"><tr><th v-for="column in columns" :key="column.key" :class="['whitespace-nowrap border-b border-[#E2E6EC] px-4 py-3 text-left text-xs font-semibold text-[#667085]', column.align === 'right' && 'text-right']" :style="column.width ? { width: column.width } : null">{{ column.label }}</th><th v-if="$slots.actions" class="border-b border-[#E2E6EC] px-4 py-3 text-right text-xs font-semibold text-[#667085]">Aksi</th></tr></thead><tbody><tr v-if="loading"><td :colspan="columns.length + ($slots.actions ? 1 : 0)" class="px-4 py-10 text-center"><LoaderCircle :size="18" class="mx-auto animate-spin text-[#667085]" /></td></tr><tr v-else-if="!rows.length"><td :colspan="columns.length + ($slots.actions ? 1 : 0)" class="px-4 py-10 text-center text-[#667085]"><Inbox :size="18" class="mx-auto mb-2 text-[#A0AABB]" />{{ emptyText }}</td></tr><tr v-else v-for="row in rows" :key="row[rowKey]" class="border-b border-[#E2E6EC] last:border-0 hover:bg-[#F9FAFB]"><td v-for="column in columns" :key="column.key" :class="['whitespace-nowrap px-4 py-3 text-[#172033]', column.align === 'right' && 'text-right']"><slot :name="`cell-${column.key}`" :row="row" :value="row[column.key]">{{ row[column.key] }}</slot></td><td v-if="$slots.actions" class="px-4 py-3 text-right"><slot name="actions" :row="row" /></td></tr></tbody></table></div></template>
